const $=s=>document.querySelector(s);const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
if($('#year'))$('#year').textContent=new Date().getFullYear();
const toggle=$('.menu-toggle'),menu=$('#navlinks');function closeMenu(){menu?.classList.remove('open');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','Open navigation')}toggle?.addEventListener('click',()=>{let open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',open);toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});menu?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(menu?.classList.contains('open')){closeMenu();toggle.focus()}}});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu()});
function scrollState(){let y=scrollY,max=document.documentElement.scrollHeight-innerHeight;$('.nav')?.classList.toggle('scrolled',y>20);$('#backtop')?.classList.toggle('visible',y>650);if($('#progress'))$('#progress').style.width=(max>0?y/max*100:0)+'%'}addEventListener('scroll',scrollState,{passive:true});addEventListener('resize',scrollState);scrollState();
if('IntersectionObserver' in window){const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');obs.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.skill,.timeline article,.finding,.report-section>div,.about-copy,.process-list article,.file-list article').forEach(el=>{if(!reduce){el.classList.add('reveal');obs.observe(el)}});const active=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('#navlinks a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('section[id]').forEach(el=>active.observe(el))}
let toastTimer;function toast(t){let el=$('.toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}$('.copy-email')?.addEventListener('click',async()=>{try{await copyAddress();$('.copy-email span').textContent='Copied!';toast('Email address copied');setTimeout(()=>$('.copy-email span').textContent='Copy',2600)}catch{toast('Please copy: mohadmuayadai@gmail.com')}});
const dlg=$('#chart-dialog');document.querySelectorAll('.chart-open').forEach(b=>b.addEventListener('click',()=>{$('#chart-image').src=b.dataset.chart;$('#chart-image').alt=b.dataset.title;$('#chart-title').textContent=b.dataset.title;dlg.showModal()}));$('.dialog-close')?.addEventListener('click',()=>dlg.close());dlg?.addEventListener('click',e=>{if(e.target===dlg){let r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));

const caseLinks=[...document.querySelectorAll('.case-nav a')];
if(caseLinks.length&&'IntersectionObserver' in window){const sections=[...new Set(caseLinks.map(a=>document.querySelector(a.hash)).filter(Boolean))];const watcher=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){caseLinks.forEach(a=>{const current=a.hash==='#'+entry.target.id;a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}}},{rootMargin:'-10% 0px -55% 0px',threshold:0});sections.forEach(s=>watcher.observe(s))}

async function copyAddress(){const address='mohadmuayadai@gmail.com';try{if(navigator.clipboard){await navigator.clipboard.writeText(address);return}}catch{}const field=document.createElement('textarea');field.value=address;field.setAttribute('readonly','');field.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('Clipboard unavailable')}

const motionToggle=document.querySelector('.motion-toggle');motionToggle?.addEventListener('click',()=>{const paused=document.querySelector('.case-nav').classList.toggle('paused');motionToggle.setAttribute('aria-pressed',String(paused));motionToggle.setAttribute('aria-label',paused?'Resume section strip motion':'Pause section strip motion');motionToggle.textContent=paused?'Resume motion':'Pause motion'});
